class LateFeePolicy:
    def __init__(self, config):
        raw = config.get("late_fee_pct")
        self.pct = None if raw is None else to_decimal(raw)
        self.running_total = ZERO

    def charge(self, row):
        if self.pct is None or self.pct <= 0:
            return None
        fee = LateFee(row.number, percent_of(row.balance, self.pct),
                      f"Late fee {self.pct}% on {fmt(row.balance)}")
        self.running_total += fee.amount
        return fee


def aging_report(ledger, config, as_of):

policy = LateFeePolicy(config)
fees = [fee for fee in (policy.charge(r) for r in rows) if fee]
return AgingReport(as_of, rows, edges, fees, policy.running_total)
